t\":null,\"role\":\"video_frame\",\"source_types\":[\"image/png\"],\"target_sample_rate\":null,\"transform\":\"video_frame_v1\"}],\"runtime\":{\"abi\":\"test_only\",\"engine\":\"deno\",\"platform\":\"synthetic\",\"protocol\":1,\"version\":\"2.9.4\"}},\"version\":1},\"resolved_manifest\":{\"assignment_digest\":\"21ecf7b3b8d543907c575fa488003c41ab121206f33bc795d5ad6f4087c3a74d\",\"entries\":[{\"object_id\":\"00000000-0000-4000-8000-000000001050\",\"ordinal\":0},{\"object_id\":\"00000000-0000-4000-8000-000000001051\",\"ordinal\":1},{\"object_id\":null,\"ordinal\":2}],\"grant_id\":\"00000000-0000-4000-8000-000000001003\",\"request_digest\":\"04fc47a8e61804631eae2178657e66914afe90b106d5a07ac1c8b259339aee5b\",\"scan_id\":\"00000000-0000-4000-8000-000000001002\",\"version\":1},\"retained\":[{\"bytes\":{\"byte_count\":68,\"content_type\":\"image/png\",\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"},\"object_id\":\"00000000-0000-4000-8000-000000001050\",\"ordinal\":0},{\"bytes\":{\"byte_count\":32044,\"content_type\":\"audio/wav\",\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"},\"object_id\":\"00000000-0000-4000-8000-000000001051\",\"ordinal\":1}],\"scan_id\":\"00000000-0000-4000-8000-000000001002\",\"source_verification\":{\"assignment_digest\":\"21ecf7b3b8d543907c575fa488003c41ab121206f33bc795d5ad6f4087c3a74d\",\"backend_generation\":\"00000000-0000-4000-8000-00000000b001\",\"entries\":[{\"bytes\":{\"byte_count\":68,\"content_type\":\"image/png\",\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"},\"facts\":{\"image\":{\"format\":\"png\",\"height\":1,\"width\":1},\"mp4\":null,\"wav\":null},\"object_id\":\"00000000-0000-4000-8000-000000001050\",\"ordinal\":0},{\"bytes\":{\"byte_count\":32044,\"content_type\":\"audio/wav\",\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"},\"facts\":{\"image\":null,\"mp4\":null,\"wav\":{\"channels\":1,\"format\":\"pcm16\",\"frames\":16000,\"sample_rate\":16000}},\"object_id\":\"00000000-0000-4000-8000-000000001051\",\"ordinal\":1},{\"bytes\":{\"byte_count\":24,\"content_type\":\"video/mp4\",\"sha256\":\"aaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaaa\"},\"facts\":{\"image\":null,\"mp4\":{\"structure\":\"bounded_mp4_accepted\"},\"wav\":null},\"object_id\":\"00000000-0000-4000-8000-000000001052\",\"ordinal\":2}],\"profile_digest\":\"bcc4b8c18220ff9ad645a3306cf230442327f00412d380119bff798e8b5c15ad\",\"scan_id\":\"00000000-0000-4000-8000-000000001002\",\"validator_identity\":\"bbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbbb\",\"version\":1},\"version\":2}","outcome_digest":"476e879d1732fd444fddfe76b044d4348643ceb04f7228bcf743e28d579cb970"}]}$originals$::JSONB v;
CREATE TEMP TABLE metadata_cases AS SELECT (i-1)::INTEGER i,x v,((SELECT v->'valid' FROM original_vectors)||(SELECT v->'extra_originals' FROM metadata_vectors))->((x->>'original_index')::INTEGER) o FROM metadata_vectors CROSS JOIN LATERAL jsonb_array_elements(v->'valid') WITH ORDINALITY z(x,i);
CREATE FUNCTION pg_temp.metadata_run(o JSONB,v JSONB) RETURNS JSONB LANGUAGE SQL AS $$
 SELECT internal.validate_initial_admission_metadata(internal.initial_canonical(o->'candidate'),internal.initial_canonical(o->'assignment'),internal.initial_canonical(o#>'{catalog,preparation}'),internal.initial_canonical(o#>'{catalog,installation}'),internal.initial_canonical(o#>'{catalog,protocol}'),internal.initial_canonical(o#>'{catalog,destination}'),(o->>'original_expires_at_ms')::NUMERIC,internal.initial_canonical(o->'outcome'),internal.initial_canonical(v->'scope'),internal.initial_canonical(v#>'{metadata,phase_window}'),internal.initial_canonical(v#>'{metadata,mapping}'),internal.initial_canonical(v#>'{metadata,media_binding}'));
$$;
CREATE FUNCTION pg_temp.metadata_rebind(o JSONB,v JSONB) RETURNS JSONB LANGUAGE PLPGSQL AS $$
DECLARE od TEXT:=internal.initial_qualified_outcome_digest(internal.initial_canonical(o->'outcome')); m JSONB:=v->'metadata';
BEGIN
 m:=jsonb_set(m,'{mapping,outcome_digest}',to_jsonb(od)); m:=jsonb_set(m,'{media_binding,outcome_digest}',to_jsonb(od));
 m:=jsonb_set(m,'{media_binding,mapping_digest}',to_jsonb(internal.initial_admission_metadata_digest('mapping',internal.initial_canonical(m->'mapping'))));
 m:=jsonb_set(m,'{media_binding,phase_window}',m->'phase_window');
 m:=jsonb_set(m,'{media_binding,phase_window_digest}',to_jsonb(internal.initial_admission_metadata_digest('phase_window',internal.initial_canonical(m->'phase_window'))));
 RETURN jsonb_set(v,'{metadata}',m);
END; $$;
SELECT extensions.is(pg_temp.metadata_run(o,v)->>'canonical_input',v->>'input_canonical','exact projected input '||i) FROM metadata_cases;
SELECT extensions.is(pg_temp.metadata_run(o,v)->>k,v->>k,'digest parity '||i||k) FROM metadata_cases CROSS JOIN unnest(ARRAY['submission_digest','descriptions_digest','phase_window_digest','mapping_digest','media_binding_digest']) k;
SELECT extensions.is(pg_temp.metadata_run(o,v)->>('canonical_'||k),internal.initial_canonical(v#>ARRAY['metadata',k]),'canonical parity '||i||k) FROM metadata_cases CROSS JOIN unnest(ARRAY['phase_window','mapping','media_binding']) k;
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_admission_metadata(%L,%L)',k,internal.initial_canonical((v#>ARRAY['metadata',k])-field)),'22023','initial_analysis_input_invalid','missing root field '||k||field) FROM metadata_cases CROSS JOIN unnest(ARRAY['phase_window','mapping','media_binding']) k CROSS JOIN LATERAL jsonb_object_keys(v#>ARRAY['metadata',k]) field WHERE i=0;
SELECT extensions.throws_ok(format('SELECT internal.parse_initial_admission_metadata(%L,%L)',k,internal.initial_canonical((v#>ARRAY['metadata',k])||bad)),'22023','initial_analysis_input_invalid','closed root '||k||bad::TEXT) FROM metadata_cases CROSS JOIN unnest(ARRAY['phase_window','mapping','media_binding']) k CROSS JOIN unnest(ARRAY['{"extra":true}'::JSONB,'{"version":99}'::JSONB,'{"admission_receipt_digest":"unused"}'::JSONB]) bad WHERE i=0;
SELECT extensions.throws_ok(format('SELECT pg_temp.metadata_run(%L::JSONB,%L::JSONB)',o,jsonb_set(v,ARRAY['metadata',k,field],to_jsonb(CASE WHEN field LIKE '%digest' THEN repeat('f',64) ELSE '00000000-0000-4000-8000-000000009999' END))),'22023','initial_analysis_input_invalid','identity substitution '||k||field) FROM metadata_cases CROSS JOIN unnest(ARRAY['phase_window','mapping','media_binding']) k CROSS JOIN LATERAL jsonb_each(v#>ARRAY['metadata',k]) z(field,value) WHERE i=0 AND jsonb_typeof(value)='string';
SELECT extensions.throws_ok(format('SELECT pg_temp.metadata_run(%L::JSONB,%L::JSONB)',o,pg_temp.metadata_rebind(o,jsonb_set(v,ARRAY['metadata','phase_window','cutoffs',phase],to_jsonb((v#>>ARRAY['metadata','phase_window','cutoffs',phase])::BIGINT+delta)))),'22023','initial_analysis_input_invalid','cutoff mismatch '||phase||delta) FROM metadata_cases CROSS JOIN jsonb_object_keys(v#>'{metadata,phase_window,cutoffs}') phase CROSS JOIN unnest(ARRAY[-1,1]) delta WHERE i=0;
CREATE FUNCTION pg_temp.metadata_boundary(v JSONB,remaining BIGINT) RETURNS JSONB LANGUAGE PLPGSQL AS $$
DECLARE w JSONB:=v#>'{metadata,phase_window}'; delta BIGINT; k TEXT;
BEGIN
 delta:=(w->>'original_expires_at_ms')::BIGINT-remaining-(w->>'anchor_ms')::BIGINT;
 w:=jsonb_set(w,'{anchor_ms}',to_jsonb((w->>'anchor_ms')::BIGINT+delta));
 FOR k IN SELECT jsonb_object_keys(w->'cutoffs') LOOP w:=jsonb_set(w,ARRAY['cutoffs',k],to_jsonb((w#>>ARRAY['cutoffs',k])::BIGINT+delta)); END LOOP;
 RETURN jsonb_set(v,'{metadata,phase_window}',w);
END; $$;
SELECT extensions.throws_ok(format('SELECT pg_temp.metadata_run(%L::JSONB,%L::JSONB)',o,pg_temp.metadata_rebind(o,pg_temp.metadata_boundary(v,remaining))),'55000','initial_analysis_handoff_budget_unavailable','strict expiry '||remaining) FROM metadata_cases CROSS JOIN unnest(ARRAY[79999,80000]) remaining WHERE i=0;
SELECT extensions.lives_ok(format('SELECT pg_temp.metadata_run(%L::JSONB,%L::JSONB)',o,pg_temp.metadata_rebind(o,pg_temp.metadata_boundary(v,80001))),'one millisecond strict margin') FROM metadata_cases WHERE i=0;
SELECT extensions.throws_ok(format('SELECT pg_temp.metadata_run(%L::JSONB,%L::JSONB)',o,jsonb_set(v,'{metadata,mapping,items,0,source}','null')),'22023','initial_analysis_input_invalid','source never nullable') FROM metadata_cases WHERE i=0;
SELECT extensions.throws_ok(format('SELECT pg_temp.metadata_run(%L::JSONB,%L::JSONB)',o,pg_temp.metadata_rebind(o,jsonb_set(v,path,bad))),'22023','initial_analysis_input_invalid',label) FROM metadata_cases CROSS JOIN (VALUES
 (ARRAY['metadata','mapping','items','0','source','destination_object_id'],'"00000000-0000-4000-8000-000000004006"'::JSONB,'raw video source collision'),
 (ARRAY['metadata','mapping','items','0','source','bytes','byte_count'],'69'::JSONB,'source bytes changed'),
 (ARRAY['metadata','mapping','items','0','index'],'1'::JSONB,'index changed'),
 (ARRAY['metadata','mapping','objects'],'[]'::JSONB,'union omitted'),
 (ARRAY['metadata','mapping','items','0','prepared'],'null'::JSONB,'image prepared omitted')
 ) z(path,bad,label) WHERE i=6;
-- Construct the exact bad source collision from the original raw-video ID.
SELECT extensions.throws_ok(format('SELECT pg_temp.metadata_run(%L::JSONB,%L::JSONB)',o,pg_temp.metadata_rebind(o,jsonb_set(v,'{metadata,mapping,items,0,source,destination_object_id}',o#>'{outcome,source_verification,entries,6,object_id}'))),'22023','initial_analysis_input_invalid','original raw source cannot be destination') FROM metadata_cases WHERE i=6;
SELECT extensions.throws_ok(format('SELECT pg_temp.metadata_run(%L::JSONB,%L::JSONB)',o,pg_temp.metadata_rebind(o,jsonb_set(v,'{metadata,mapping,items,1,source,destination_object_id}',v#>'{metadata,mapping,items,0,source,destination_object_id}'))),'22023','initial_analysis_input_invalid','cross ordinal alias') FROM metadata_cases WHERE i=6;
SELECT extensions.throws_ok(format('SELECT pg_temp.metadata_run(%L::JSONB,%L::JSONB)',o,pg_temp.metadata_rebind(o,jsonb_set(v,'{metadata,mapping,items,0,prepared,destination_object_id}',CASE WHEN i=7 THEN '"00000000-0000-4000-8000-000000008888"'::JSONB ELSE v#>'{metadata,mapping,items,0,source,destination_object_id}' END))),'22023','initial_analysis_input_invalid','alias equivalence '||i) FROM metadata_cases WHERE i IN(7,8);
SELECT extensions.throws_ok(format('SELECT pg_temp.metadata_run(%L::JSONB,%L::JSONB)',jsonb_set(o,'{outcome,source_verification,entries,0,bytes,sha256}',to_jsonb(repeat('f',64))),v),'22023','initial_analysis_input_invalid','original proof altered') FROM metadata_cases WHERE i=0;
SELECT extensions.throws_ok(format('SELECT internal.initial_admission_metadata_digest(%L,%L)',k,internal.initial_canonical(v#>'{metadata,mapping}')),'22023','initial_analysis_input_invalid','no unsupported digest domain '||k) FROM metadata_cases CROSS JOIN unnest(ARRAY['scope','admitted_receipt','unrecognized']) k WHERE i=0;
SELECT extensions.throws_ok(format('SELECT internal.initial_admission_metadata_digest(%L,%L)','mapping',' '||internal.initial_canonical(v#>'{metadata,mapping}')),'22023','initial_analysis_input_invalid','noncanonical text') FROM metadata_cases WHERE i=0;
SELECT extensions.ok(NOT has_function_privilege(r,s,'EXECUTE'),'private helper '||r||s) FROM unnest(ARRAY['anon','authenticated','service_role']) r CROSS JOIN unnest(ARRAY['internal.initial_admission_metadata_schema()','internal.parse_initial_admission_metadata(text,text)','internal.initial_admission_metadata_digest(text,text)','internal.validate_initial_admission_metadata(text,text,text,text,text,text,numeric,text,text,text,text,text)']) s;
SELECT extensions.is((SELECT initial_analysis_lifecycle_enabled FROM internal.initial_analysis_rollout),FALSE,'activation remains false');
-- Rebase the whole original/window to the largest shared integer, preserving durations.
CREATE TEMP TABLE metadata_safe AS SELECT o,v,9007199254740991-(o->>'original_expires_at_ms')::BIGINT delta FROM metadata_cases WHERE i=0;
DO $$ DECLARE r RECORD; k TEXT; g JSONB; w JSONB; BEGIN
 FOR r IN SELECT * FROM metadata_safe LOOP
  r.o:=jsonb_set(r.o,'{original_expires_at_ms}',to_jsonb(9007199254740991::BIGINT)); g:=r.o#>'{outcome,grant}';
  FOREACH k IN ARRAY ARRAY['issued_at_ms','execution_deadline_ms','registration_deadline_ms','outcome_deadline_ms','preparation_expires_at_ms'] LOOP g:=jsonb_set(g,ARRAY[k],to_jsonb((g->>k)::BIGINT+r.delta)); END LOOP;
  r.o:=jsonb_set(r.o,'{outcome,grant}',g); w:=r.v#>'{metadata,phase_window}';
  FOREACH k IN ARRAY ARRAY['anchor_ms','original_expires_at_ms'] LOOP w:=jsonb_set(w,ARRAY[k],to_jsonb((w->>k)::BIGINT+r.delta)); END LOOP;
  FOR k IN SELECT jsonb_object_keys(w->'cutoffs') LOOP w:=jsonb_set(w,ARRAY['cutoffs',k],to_jsonb((w#>>ARRAY['cutoffs',k])::BIGINT+r.delta)); END LOOP;
  r.v:=pg_temp.metadata_rebind(r.o,jsonb_set(r.v,'{metadata,phase_window}',w)); UPDATE metadata_safe SET o=r.o,v=r.v;
 END LOOP;
END $$;
SELECT extensions.lives_ok(format('SELECT pg_temp.metadata_run(%L::JSONB,%L::JSONB)',o,v),'largest shared integer window') FROM metadata_safe;
